#include <iostream>
#include <sstream>
#include <iomanip>
#include <vector>
#include <cstring>

struct ClientData {
    unsigned int acctNum{0};
    char lastName[15]{""};
    char firstName[10]{""};
    double balance{0.0};
};

void textFile(std::iostream& readStream, std::ostream& reportOut) {
    readStream.clear();
    readStream.seekg(0, std::ios::beg);

    reportOut << std::left << std::setw(6) << "Acct"
              << std::setw(16) << "Last Name"
              << std::setw(11) << "First Name"
              << std::right << std::setw(10) << "Balance" << "\n";

    ClientData client;
    while (readStream.read(reinterpret_cast<char*>(&client), sizeof(ClientData))) {
        if (client.acctNum != 0) {
            reportOut << std::left << std::setw(6) << client.acctNum
                      << std::setw(16) << client.lastName
                      << std::setw(11) << client.firstName
                      << std::right << std::setw(10) << std::fixed << std::setprecision(2)
                      << client.balance << "\n";
        }
    }
}

int main() {
    // Simulate random-access binary file in memory with 10 slots
    std::stringstream file(std::ios::in | std::ios::out | std::ios::binary);
    std::vector<ClientData> table(10);

    // Populate sample account 37
    table[6].acctNum = 37;
    std::strncpy(table[6].lastName, "Barker", 14);
    std::strncpy(table[6].firstName, "Doug", 9);
    table[6].balance = 0.00;

    // Populate sample account 88
    table[8].acctNum = 88;
    std::strncpy(table[8].lastName, "Smith", 14);
    std::strncpy(table[8].firstName, "Dave", 9);
    table[8].balance = 258.34;

    file.write(reinterpret_cast<const char*>(table.data()), table.size() * sizeof(ClientData));

    textFile(file, std::cout);
    return 0;
}

#include <iostream>
#include <sstream>
#include <iomanip>
#include <vector>
#include <cstring>

struct ClientData {
    unsigned int acctNum{0};
    char lastName[15]{""};
    char firstName[10]{""};
    double balance{0.0};
};

bool updateRecord(std::iostream& recordStream, unsigned int account, double transaction) {
    std::streamoff offset = static_cast<std::streamoff>((account - 1) * sizeof(ClientData));

    // 1. Move to record offset and read existing data
    recordStream.seekg(offset);
    ClientData client;
    recordStream.read(reinterpret_cast<char*>(&client), sizeof(ClientData));

    if (client.acctNum == 0) {
        std::cout << "Account #" << account << " has no information.\n";
        return false;
    }

    // 2. Adjust balance
    client.balance += transaction;

    // 3. Crucial step: Reposition back to the exact same offset before writing
    recordStream.seekp(offset);
    recordStream.write(reinterpret_cast<const char*>(&client), sizeof(ClientData));
    return true;
}

int main() {
    // Setup in-memory stream representing random access binary file
    std::stringstream storage(std::ios::in | std::ios::out | std::ios::binary);
    std::vector<ClientData> accounts(100);

    // Initialize account 37
    accounts[36].acctNum = 37;
    std::strncpy(accounts[36].lastName, "Barker", 14);
    accounts[36].firstName, "Doug", 9;
    accounts[36].balance = 0.00;

    storage.write(reinterpret_cast<const char*>(accounts.data()), accounts.size() * sizeof(ClientData));

    // Read user input from stdin: account number and transaction amount
    unsigned int accountNum;
    double transactionAmount;
    if (std::cin >> accountNum >> transactionAmount) {
        if (updateRecord(storage, accountNum, transactionAmount)) {
            storage.seekg(static_cast<std::streamoff>((accountNum - 1) * sizeof(ClientData)));
            ClientData verified;
            storage.read(reinterpret_cast<char*>(&verified), sizeof(ClientData));

            std::cout << std::left << std::setw(6) << verified.acctNum
                      << std::setw(16) << verified.lastName
                      << std::setw(11) << verified.firstName
                      << std::right << std::setw(10) << std::fixed << std::setprecision(2)
                      << verified.balance << "\n";
        }
    }
    return 0;
}

#include <iostream>
#include <sstream>
#include <iomanip>
#include <string>
#include <vector>
#include <cstring>

struct ClientData {
    unsigned int acctNum{0};
    char lastName[15]{""};
    char firstName[10]{""};
    double balance{0.0};
};

bool newRecord(std::iostream& recordStream, unsigned int acct, const std::string& last, const std::string& first, double bal) {
    std::streamoff offset = static_cast<std::streamoff>((acct - 1) * sizeof(ClientData));
    recordStream.seekg(offset);
    ClientData client;
    recordStream.read(reinterpret_cast<char*>(&client), sizeof(ClientData));

    if (client.acctNum != 0) {
        std::cout << "Account #" << acct << " already contains information.\n";
        return false;
    }

    client.acctNum = acct;
    std::strncpy(client.lastName, last.c_str(), 14);
    client.lastName[14] = '\0';
    std::strncpy(client.firstName, first.c_str(), 9);
    client.firstName[9] = '\0';
    client.balance = bal;

    recordStream.seekp(offset);
    recordStream.write(reinterpret_cast<const char*>(&client), sizeof(ClientData));
    return true;
}

bool deleteRecord(std::iostream& recordStream, unsigned int acct) {
    std::streamoff offset = static_cast<std::streamoff>((acct - 1) * sizeof(ClientData));
    recordStream.seekg(offset);
    ClientData client;
    recordStream.read(reinterpret_cast<char*>(&client), sizeof(ClientData));

    if (client.acctNum == 0) {
        std::cout << "Account " << acct << " does not exist.\n";
        return false;
    }

    ClientData blankClient{0, "", "", 0.0};
    recordStream.seekp(offset);
    recordStream.write(reinterpret_cast<const char*>(&blankClient), sizeof(ClientData));
    return true;
}

int main() {
    std::stringstream storage(std::ios::in | std::ios::out | std::ios::binary);
    std::vector<ClientData> initSlots(100);
    storage.write(reinterpret_cast<const char*>(initSlots.data()), initSlots.size() * sizeof(ClientData));

    // Read input from stdin: account to add, lastname, firstname, balance, then account to delete
    unsigned int addAcct;
    std::string last, first;
    double bal;
    unsigned int delAcct;

    if (std::cin >> addAcct >> last >> first >> bal >> delAcct) {
        newRecord(storage, addAcct, last, first, bal);

        storage.seekg(static_cast<std::streamoff>((addAcct - 1) * sizeof(ClientData)));
        ClientData rec;
        storage.read(reinterpret_cast<char*>(&rec), sizeof(ClientData));
        std::cout << "Added: " << rec.acctNum << " " << rec.lastName << " " << std::fixed << std::setprecision(2) << rec.balance << "\n";

        deleteRecord(storage, delAcct);

        storage.seekg(static_cast<std::streamoff>((delAcct - 1) * sizeof(ClientData)));
        storage.read(reinterpret_cast<char*>(&rec), sizeof(ClientData));
        std::cout << "After delete, acctNum: " << rec.acctNum << "\n";
    }
    return 0;
}
